fn not_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Initialize a boolean vector with the same length as the input vectors
    let mut result = Vec::with_capacity(a.len());
    
    // Iterate through both vectors and compare elements
    for (x, y) in a.iter().zip(b.iter()) {
        result.push(x != y); // Push true if elements are not equal, false otherwise
    }
    
    result // Return the resulting boolean vector
}